window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-652bc9a4f08d38dc"]={"versions": [{"id": "FIG-652bc9a4f08d38dc", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Rahmen des AUTOSAR Basic Software (BSW) UML Model Modeling Guide. Es illustriert die Modellierungsmethodik für generische Schnittstellen (<code>«generic_interface»</code>) und deren Spezialisierung bzw. Realisierung durch BSW-Module (hier am Beispiel des Moduls <code>Xcp</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>«module» <code>Xcp</code></strong>: Repräsentiert das BSW-Modul XCP. Enthält Tags:</li>\n<li><code>bsw.importedTypes.swsItemId = SWS_Xcp_00801</code></li>\n<li><code>bsw.importedTypes.traceRefs =</code></li>\n<li><code>bsw.optional.swsItemId = SWS_Xcp_00832</code></li>\n<li><code>bsw.optional.traceRefs =</code></li>\n<li><strong>«generic_interface» <code>TriggerTransmit</code></strong>: Lokales bzw. abgeleitetes generisches Interface mit Tags zur Namensbildung:</li>\n<li><code>naming_configurable = &lt;User_[name]&gt;</code></li>\n<li><code>naming_provider = [provider]_&lt;Lo&gt;[name]</code></li>\n<li><code>naming_user = [provider]_[user][name]</code></li>\n<li><strong>«generic_interface» <code>GenericComServices::TriggerTransmit</code></strong>: Übergeordnetes generisches Blueprint-Interface im Package <code>GenericComServices</code>.</li>\n<li>Enthält die Operation <code>«function_blueprint» + TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>.</li>\n<li>Tags:</li>\n<li><code>naming_configurable = &lt;User_[name]&gt;</code></li>\n<li><code>naming_provider = [provider]_[name]</code></li>\n<li><code>naming_user = [provider]_[name]</code></li>\n<li><strong>Beziehungen</strong>:</li>\n<li><code>Xcp</code> realisiert <code>TriggerTransmit</code> über eine <code>«realize»</code>-Abhängigkeit (gestrichelter Pfeil mit geschlossener, nicht ausgefüllter Pfeilspitze).</li>\n<li><code>TriggerTransmit</code> erbt von bzw. spezialisiert <code>GenericComServices::TriggerTransmit</code> über eine Generalisierungsbeziehung (durchgezogene Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Schnittstellen- und Metamodell-Struktur ohne zeitliche Ablauf- oder Sequenzpfade. Zur Laufzeit erfolgt die Auslösung der Übertragung über den durch das Blueprint-Muster vorgegebenen Funktionsaufruf <code>TriggerTransmit</code> mit Rückgabetyp <code>Std_ReturnType</code> und den Parametern <code>PduIdType</code> und Zeiger auf <code>PduInfoType</code>. Die konkreten C-Funktionsnamen werden dabei gemäß den definierten Tag-Mustern (<code>naming_provider</code>, <code>naming_user</code>, <code>naming_configurable</code>) generiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindliche Modellierungsvorgaben für BSW-UML-Modelle:</p>\n<ul class=\"fig-list\">\n<li>Generische Kommunikationsdienste werden als <code>«generic_interface»</code> mit <code>«function_blueprint»</code> modelliert.</li>\n<li>Modul-Spezialisierungen leiten sich per Vererbung ab und passen ggf. Namenskonventionen über spezifische Tag-Werte an (z. B. Einfügen von <code>&lt;Lo&gt;</code> in <code>naming_provider</code>).</li>\n<li>Implementierende Module binden das Schnittstellenmuster über eine <code>«realize»</code>-Beziehung ein.</li>\n<li>Traceability-Anforderungen zu den jeweiligen SWS-Anforderungen werden über BSW-spezifische Tags (<code>swsItemId</code>, <code>traceRefs</code>) dokumentiert.</li>\n</ul>"}, {"id": "FIG-a5d21ebc9322186e", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Komponentendiagramm im Rahmen des AUTOSAR Basic Software (BSW) UML Model Modeling Guide. Es illustriert die Modellierungsmethodik für generische Schnittstellen (<code>«generic_interface»</code>) und deren Spezialisierung bzw. Realisierung durch BSW-Module (hier am Beispiel des Moduls <code>Xcp</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>«module» <code>Xcp</code></strong>: Repräsentiert das BSW-Modul XCP. Enthält Tags:</li>\n<li><code>bsw.importedTypes.swsItemId = SWS_Xcp_00801</code></li>\n<li><code>bsw.importedTypes.traceRefs =</code></li>\n<li><code>bsw.optional.swsItemId = SWS_Xcp_00832</code></li>\n<li><code>bsw.optional.traceRefs =</code></li>\n<li><strong>«generic_interface» <code>TriggerTransmit</code></strong>: Lokales bzw. abgeleitetes generisches Interface mit Tags zur Namensbildung:</li>\n<li><code>naming_configurable = &lt;User_[name]&gt;</code></li>\n<li><code>naming_provider = [provider]_&lt;Lo&gt;[name]</code></li>\n<li><code>naming_user = [provider]_[user][name]</code></li>\n<li><strong>«generic_interface» <code>GenericComServices::TriggerTransmit</code></strong>: Übergeordnetes generisches Blueprint-Interface im Package <code>GenericComServices</code>.</li>\n<li>Enthält die Operation <code>«function_blueprint» + TriggerTransmit(Std_ReturnType, PduIdType, PduInfoType*)</code>.</li>\n<li>Tags:</li>\n<li><code>naming_configurable = &lt;User_[name]&gt;</code></li>\n<li><code>naming_provider = [provider]_[name]</code></li>\n<li><code>naming_user = [provider]_[name]</code></li>\n<li><strong>Beziehungen</strong>:</li>\n<li><code>Xcp</code> realisiert <code>TriggerTransmit</code> über eine <code>«realize»</code>-Abhängigkeit (gestrichelter Pfeil mit geschlossener, nicht ausgefüllter Pfeilspitze).</li>\n<li><code>TriggerTransmit</code> erbt von bzw. spezialisiert <code>GenericComServices::TriggerTransmit</code> über eine Generalisierungsbeziehung (durchgezogene Linie mit geschlossener, nicht ausgefüllter Pfeilspitze).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Schnittstellen- und Metamodell-Struktur ohne zeitliche Ablauf- oder Sequenzpfade. Zur Laufzeit erfolgt die Auslösung der Übertragung über den durch das Blueprint-Muster vorgegebenen Funktionsaufruf <code>TriggerTransmit</code> mit Rückgabetyp <code>Std_ReturnType</code> und den Parametern <code>PduIdType</code> und Zeiger auf <code>PduInfoType</code>. Die konkreten C-Funktionsnamen werden dabei gemäß den definierten Tag-Mustern (<code>naming_provider</code>, <code>naming_user</code>, <code>naming_configurable</code>) generiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert verbindliche Modellierungsvorgaben für BSW-UML-Modelle:</p>\n<ul class=\"fig-list\">\n<li>Generische Kommunikationsdienste werden als <code>«generic_interface»</code> mit <code>«function_blueprint»</code> modelliert.</li>\n<li>Modul-Spezialisierungen leiten sich per Vererbung ab und passen ggf. Namenskonventionen über spezifische Tag-Werte an (z. B. Einfügen von <code>&lt;Lo&gt;</code> in <code>naming_provider</code>).</li>\n<li>Implementierende Module binden das Schnittstellenmuster über eine <code>«realize»</code>-Beziehung ein.</li>\n<li>Traceability-Anforderungen zu den jeweiligen SWS-Anforderungen werden über BSW-spezifische Tags (<code>swsItemId</code>, <code>traceRefs</code>) dokumentiert.</li>\n</ul>"}], "trans": [{"from": "FIG-652bc9a4f08d38dc", "to": "FIG-a5d21ebc9322186e", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
